der_date >= \'2024-10-24\' group by 1 ) select a.*, b.offline_real, c.shopify_real, d.marketplace_real from predicted_sales a left join offline_actual_sales b on a.date = b.date left join shopify_actual_sales c on a.date = c.date left join marketplace_sales d on a.date = d.date ; ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.shopify_prediction_sales as ( with last_week_performance as ( select sum(appbrew_sessions)+sum(web_sessions)+sum(ifnull(app_ios_sessions,0)+ifnull(app_android_sessions,0)) as sessions, sum(gross_sales) as gross_sales, sum(total_orders) as gross_orders from snitch_db.maplemonk.sales_cost_source_snitch where date < current_date - 1 and date > current_date - 9 ), final_metrics as ( select sessions/gross_sales as sessions_per_gross_sales, gross_sales/gross_orders as aov, gross_orders/sessions as conversion from last_week_performance ), targets as ( select a.date, cast(a.shopify_sarima as number) as targeted_sales, round(a.shopify_sarima * b.sessions_per_gross_sales,0) as targeted_sessions, round(b.aov,0) as aov, round((a.shopify_sarima / b.aov),0) as targeted_orders from snitch_db.maplemonk.prediction_sarima_xgboost a cross join final_metrics b ), actual as ( select b.date, round(sum(b.gross_sales),0) as actual_sales, sum(b.total_orders) as actual_orders, round(sum(b.appbrew_sessions)+sum(b.web_sessions)+sum(ifnull(b.app_ios_sessions,0)+ifnull(b.app_android_sessions,0)),0) as actual_sessions, round(sum(b.gross_sales)/sum(b.total_orders),0) as actual_aov from snitch_db.maplemonk.sales_cost_source_snitch b group by b.date ) select a.*, b.actual_sales,b.actual_orders,b.actual_sessions,b.actual_aov from targets a left join actual b on a.date = b.date );",
